  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --surface: #161b22;
      --surface-strong: #21262d;
      --text: #f0f6fc;
      --muted: #c9d1d9;
      --accent: #58a6ff;
      --accent-strong: #1f6feb;
      --border: #30363d;
      --focus: #f0b72f;
      --success: #7ee787;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, #1f3b57 0, transparent 34rem),
