      top: 1rem;
      z-index: 10;
      padding: 0.75rem 1rem;
      color: #08111f;
      background: var(--focus);
      border-radius: 0.6rem;
      transform: translateY(-150%);
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 0.2rem solid #ffffff;
      outline-offset: 0.15rem;
    }

    main {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 34rem);
      padding: clamp(1.5rem, 5vw, 2.5rem);
      background: color-mix(in srgb, var(--surface) 92%, transparent);
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      box-shadow: 0 1.5rem 4rem rgb(0 0 0 / 45%);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 8vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 1rem;
      color: var(--text);
      font-size: 1.15rem;
      font-weight: 700;
    }

    .form-field {
      margin-bottom: 1.5rem;
    }

    .required {
      color: var(--focus);
      font-weight: 700;
    }

    .radio-group {
      display: grid;
      gap: 0.85rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      min-width: 0;
      padding: 1rem;
      color: var(--text);
      background: var(--surface-strong);
      border: 1px solid var(--border);
      border-radius: 1rem;
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      background: #28313c;
      border-color: #6e7681;
    }

    .radio-option:has(input:checked) {
      background: #10243a;
      border-color: var(--accent);
      box-shadow: inset 0 0 0 1px var(--accent);
    }

    input[type="radio"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    input[type="radio"]:focus-visible,
    button:focus-visible {
      outline: 0.2rem solid var(--focus);
      outline-offset: 0.2rem;
    }

    button {
      width: 100%;
      padding: 0.9rem 1rem;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent-strong), #8250df);
      border: 1px solid #8b949e;
      border-radius: 0.9rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.12);
    }

    button:active {
      transform: translateY(1px);
    }

    .status {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 24rem) {
      main {
        padding-inline: 0.75rem;
      }

      .card {
        border-radius: 1rem;
      }

      .radio-option {
        padding: 0.85rem;
      }
    }

    @media (forced-colors: active) {
      .card,
      .radio-option,
      button {
        border-color: ButtonBorder;
        box-shadow: none;
      }

      input[type="radio"]:focus-visible,
      button:focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose how you would like us to contact you about important updates.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset>
            <legend>
              How do you prefer to receive notifications?
              <span class="required" aria-hidden="true">*</span>
            </legend>

            <div class="radio-group">
              <label class="radio-option">
                <input type="radio" name="notification-method" value="Email" required>
                <span>Email</span>
              </label>

              <label class="radio-option">
                <input type="radio" name="notification-method" value="SMS">
                <span>SMS</span>
              </label>

              <label class="radio-option">
                <input type="radio" name="notification-method" value="Push Notifications">
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Submit preference</button>
        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const status = document.querySelector("#form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = form.querySelector('input[name="notification-method"]:checked');

      if (!selected) {
        status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
        form.querySelector('input[name="notification-method"]').focus();
        return;
      }

      status.textContent = `Preference saved: ${selected.value}.`;
    });
  </script>
</body>
</html>
